# Rencana seri "Git dan Kerja Tim". Setiap episode = daftar beat (narasi, [bagian visual]).
#   R(src, a, b, crop)  potongan rekaman (a/b = nama tanda, bisa "tanda+2.5")
#   A(nama, **arg)      adegan kanvas (adegan_git.js)
#   TB(src, tanda)      kartu "Tebak dulu" di atas bingkai rekaman pada tanda itu (hitung mundur, tanpa narasi)
def R(src, a, b, crop="full", speed=1.0, maks=1.6, lab=None, labw=None, **k): return dict(k="rek", src=src, a=a, b=b, crop=crop, speed=speed, maks=maks, lab=lab, labw=labw, **k)
def A(nama, min=4, bobot=1, s=None, **arg):
    d = dict(k="adegan", nama=nama, min=min, bobot=bobot, a=arg)
    if s is not None: d["s"] = s
    return d
def TB(src, tanda, crop="full", D=5.5): return dict(k="tebak", src=src, tanda=tanda, crop=crop, min=D, bobot=0)
#   s=k pada R/A: bagian itu mulai tepat saat kalimat ke-k (dari 0) narasi beat diucapkan (sinkron narasi-visual)
def BAB(no, judul, semua, sub=None, D=4.2):
    """Kartu antarbab tanpa narasi: jeda ±4 detik supaya tutorial mudah diikuti."""
    return ("", [A("kartuBab", min=D, no=no, judul=judul, semua=semua, sub=sub)])

